/* ---------- the ticket board: #vi-board, #werk-board-columns, #werk-board-control ---------- */
body.view-board main{max-width:none}
#board-view[hidden]{display:none}
.board{position:relative}
.board-msg{margin:0 0 10px;padding:7px 12px;border:1px solid var(--stale);border-radius:6px;
  background:rgba(248,81,73,.08);color:var(--ink);font-size:12.5px}
.board-msg[hidden]{display:none}
.bcols{display:grid;grid-template-columns:repeat(5,minmax(150px,1fr));gap:10px;align-items:stretch}
.bcol{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:8px;min-height:140px;
  display:flex;flex-direction:column;transition:border-color .1s}
.bcol.drop-ok{border-color:var(--proto);background:#152030}
.bcol h3{margin:2px 4px 8px;font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);
  font-weight:600;display:flex;align-items:center;gap:6px}
.bcount{color:var(--dim);font-weight:400;letter-spacing:0}
.bcards{display:flex;flex-direction:column;gap:6px;max-height:52vh;overflow:auto;min-height:60px}
.tcard{display:flex;align-items:center;flex-wrap:wrap;gap:4px 6px;padding:7px 9px;background:var(--panel2);border:1px solid var(--line);
  border-radius:6px;cursor:pointer;font-size:13px;line-height:1.35}
.tcard:hover{border-color:var(--line2)}
.tcard.sel{border-color:var(--proto)}
.tcard.tlive{border-color:#2f5d8f}
.tcard[draggable="true"]{cursor:grab}
.tcard.dragging{opacity:.4}
.tc-title{flex:1 1 100px;min-width:0;overflow-wrap:anywhere}
.tb{flex:none;font-size:10.5px;padding:0 5px;border-radius:8px;border:1px solid var(--line2);color:var(--dim);
  line-height:16px;font-variant-numeric:tabular-nums}
.tb-block{color:var(--open);border-color:rgba(210,153,34,.5)}
.tb-heldout{color:#fff;background:var(--stale);border-color:var(--stale);cursor:pointer}
/* #st-heldout-notrun: grey, not red — the binder could not run the step */
.tb-notrun{color:var(--dim);background:var(--panel);border-color:var(--line2);border-style:dashed}
.tc-trigger{flex:none;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;font-size:9px;
  color:var(--decided);border:1px solid rgba(63,185,80,.5);text-align:center}
.tc-trigger:hover{background:rgba(63,185,80,.15)}
.tc-trigger:disabled{color:var(--faint);border-color:var(--line2);cursor:not-allowed;background:none}
.drop-line{height:2px;background:var(--proto);border-radius:1px;flex:none}

.ticket-drawer{margin-top:14px;background:var(--panel);border:1px solid var(--line2);border-radius:8px}
.ticket-drawer[hidden]{display:none}
.td-head{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line)}
.td-head h2{margin:0;font-size:15px;flex:1;min-width:0;display:flex;align-items:center;gap:8px;
  letter-spacing:0;text-transform:none;color:var(--ink);font-weight:600}
.td-id,.td-col{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px;color:var(--dim)}
.td-col{padding:1px 7px;border:1px solid var(--line2);border-radius:8px}
.td-archive{font-size:12px;padding:3px 10px;border:1px solid var(--line2);border-radius:6px;color:var(--dim)}
.td-archive:hover{color:var(--ink);border-color:var(--dim)}
.td-close{font-size:18px;line-height:1;color:var(--dim);padding:0 4px}
